        if w in note_words:
            total += 1
    return total

def top_notes(notes, question, k=2):
    ranked = sorted(notes, key=lambda n: score(n, question),
                    reverse=True)
    chosen = []
    for note in ranked:
        if score(note, question) > 0:
            chosen.append(note)
    return chosen[:k]

HEADER = [
    "Answer using only the notes below.",
    "If the notes do not cover it, say so.",
    'Reply in JSON: {"answer": "...", "note_ids": [1]}',
]

def build_prompt(question, chosen):
    lines = HEADER + ["", "Notes:"]
    for note in chosen:
        lines.append(f"[{note['id']}] {note['title']}: {note['text']}")
    lines.append("")
    lines.append("Question: " + question)
    return "\n".join(lines)

def parse_reply(raw):
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        return None
    if not isinstance(data, dict):
        return None
    if "answer" not in data or "note_ids" not in data:
        return None
    return data

def note_ids(chosen):
    ids = []
    for note in chosen:
        ids.append(note["id"])
    return ids

def check_reply(reply, chosen):
    problems = []
    sent = note_ids(chosen)
    for n in reply["note_ids"]:
        if n not in sent:
            problems.append(f"cites note {n}, which was not sent")
    used = 0
    for note in chosen:
        used += score(note, reply["answer"])
    if used == 0:
        problems.append("answer does not use the notes")
    return problems

EMAIL = r"[\w.]+@[\w.]+\.[a-z]+"
PHONE = r"\d{3}[ -]\d{3}[ -]\d{4}"
BLOCKED = ["password", "api_key"]

def redact(text):
    text = re.sub(EMAIL, "[EMAIL]", text)
    text = re.sub(PHONE, "[PHONE]", text)
    return text

def safe_to_send(prompt):
    for word in BLOCKED:
        if word in prompt.lower():
            return False
    return True

# A stand-in for a real model: canned replies, no network
def fake_model(prompt):
    if "random results" in prompt:
        return '{"answer": "Call random.seed(n) first.", ' \
               '"note_ids": [5, 9]}'
    return ('{"answer": "Use d.get(key, default) to avoid it.", '
            '"note_ids": [2]}')

QUESTIONS = [
    "How do I stop an error when a key is missing?",
    "My password is hunter2. Why does my code fail?",
    "What is a decorator?",
    "How do I make random results repeat?",
]

def run_assistant(question):
    print("Question:", question)
    chosen = top_notes(notes, question)
    if not chosen:
        print("No matching notes. Write a note first.")
        return "no notes"
    prompt = redact(build_prompt(question, chosen))
    if not safe_to_send(prompt):
        print("Blocked: the prompt holds a secret.")
        return "blocked"
    raw = fake_model(prompt)
    reply = parse_reply(raw)
    if reply is None:
        print("Could not read the reply.")
        return "bad reply"
    print("Notes sent:", note_ids(chosen))
    print("Answer:", reply["answer"])
    problems = check_reply(reply, chosen)
    if problems:
        print("Checks failed:", "; ".join(problems))
        return "failed"
    print("Checks: passed")
    return "passed"

passed = 0
for q in QUESTIONS:
    if run_assistant(q) == "passed":
        passed += 1
    print()
print(f"=== Report: {passed} of {len(QUESTIONS)} passed ===")
